struct Mode { int subsets, partbits, pbits, rotbits, idxmodebits, cbits, abits, cdepth, adepth; };
static const Mode k_modes[8] = {{3, 4, 6, 0, 0, 3, 0, 4, 0}, {2, 6, 2, 0, 0, 3, 0, 6, 0}, {3, 6, 0, 0, 0, 2, 0, 5, 0},
                                {2, 6, 4, 0, 0, 2, 0, 7, 0}, {1, 0, 0, 2, 1, 2, 3, 5, 6}, {1, 0, 0, 2, 0, 2, 2, 7, 8},
                                {1, 0, 2, 0, 0, 4, 0, 7, 7}, {2, 6, 4, 0, 0, 2, 0, 5, 5}};
static const uint8_t k_w2[4] = {0, 21, 43, 64}, k_w3[8] = {0, 9, 18, 27, 37, 46, 55, 64},
                     k_w4[16] = {0, 4, 9, 13, 17, 21, 26, 30, 34, 38, 43, 47, 51, 55, 60, 64};
inline int weight(int bits, int i) { return bits == 2 ? k_w2[i] : bits == 3 ? k_w3[i] : k_w4[i]; }
struct Bits {
    const uint8_t* b; int pos = 0;
    int get(int n) {
        int v = 0;
        for (int i = 0; i < n; i++, pos++) v |= ((b[pos >> 3] >> (pos & 7)) & 1) << i;
        return v;
    }
};
inline int unq(int c, int bits, int pbit) {
    const int shift = 8 - bits;
    int v = c << shift;
    if (pbit >= 0) v |= v >> (bits + 1), v |= pbit << (shift - 1);
    else v |= v >> bits;
    return v & 255;
}
// one 16-byte block -> 16 RGBA8 pixels (row-major 4 x 4)
inline void decode_block(const uint8_t* blk, uint8_t out[64]) {
    int mode = 0;
    while (mode < 8 && !((blk[0] >> mode) & 1)) mode++;
    if (mode == 8) { memset(out, 0, 64); return; }
    const Mode& m = k_modes[mode];
    Bits r{blk, mode + 1};
    const int partition = r.get(m.partbits), rotation = r.get(m.rotbits), idxmode = r.get(m.idxmodebits);
    const int ne = m.subsets * 2;
    int ep[6][4];
    for (int c = 0; c < 3; c++)
        for (int i = 0; i < ne; i++) ep[i][c] = r.get(m.cdepth);
    for (int i = 0; i < ne; i++) ep[i][3] = m.adepth ? r.get(m.adepth) : 255;
    int pv[6] = {};
    for (int i = 0; i < m.pbits; i++) pv[i] = r.get(1);
    for (int i = 0; i < ne; i++) {
        const int pb = m.pbits ? pv[i * m.pbits / ne] : -1;
        for (int c = 0; c < 3; c++) ep[i][c] = unq(ep[i][c], m.cdepth, pb);
        ep[i][3] = m.adepth ? unq(ep[i][3], m.adepth, pb) : 255;
    }
    const uint8_t* pt = k_part[(m.subsets - 1) * 64 + partition];
    const uint8_t* fx = k_fixup[(m.subsets - 1) * 64 + partition];
    int ci[16], ai[16] = {};
    for (int i = 0; i < 16; i++) ci[i] = r.get(i == fx[pt[i]] ? m.cbits - 1 : m.cbits);
    if (m.abits)
        for (int i = 0; i < 16; i++) ai[i] = r.get(i ? m.abits : m.abits - 1);
    for (int i = 0; i < 16; i++) {
        const int s = pt[i];
        const int* a = ep[2 * s];
        const int* b = ep[2 * s + 1];
        int wc, wa;
        if (m.abits) {
            if (!idxmode) wc = weight(m.cbits, ci[i]), wa = weight(m.abits, ai[i]);
            else wc = weight(m.abits, ai[i]), wa = weight(m.cbits, ci[i]);
        } else wc = wa = weight(m.cbits, ci[i]);
        int px[4];
        for (int c = 0; c < 3; c++) px[c] = (a[c] * (64 - wc) + b[c] * wc + 32) >> 6;
        px[3] = (a[3] * (64 - wa) + b[3] * wa + 32) >> 6;
        if (rotation) std::swap(px[3], px[rotation - 1]);
        for (int c = 0; c < 4; c++) out[i * 4 + c] = (uint8_t)px[c];
    }
}
// mode 6 (one subset, RGBA 7 bits + p-bit, 4-bit indices): endpoints at the block's per-channel min / max, the p-bits
// tried in all 4 ways, indices by projection onto the endpoint line
inline void encode_block_mode6(const uint8_t in[64], uint8_t blk[16]) {
    int lo[4] = {255, 255, 255, 255}, hi[4] = {0, 0, 0, 0};
    for (int i = 0; i < 16; i++)
        for (int c = 0; c < 4; c++) lo[c] = std::min(lo[c], (int)in[i * 4 + c]), hi[c] = std::max(hi[c], (int)in[i * 4 + c]);
    long best_err = -1;
    int best_e[2][4] = {}, best_p[2] = {}, best_idx[16] = {};
    for (int p0 = 0; p0 < 2; p0++)
        for (int p1 = 0; p1 < 2; p1++) {
            int e[2][4], q[2][4];
            for (int c = 0; c < 4; c++) {
                // 8-bit value v = (q << 1 | p): q = clamp((v - p + 1) / 2)
                q[0][c] = std::clamp((lo[c] - p0 + 1) >> 1, 0, 127), q[1][c] = std::clamp((hi[c] - p1 + 1) >> 1, 0, 127);
                e[0][c] = q[0][c] << 1 | p0, e[1][c] = q[1][c] << 1 | p1;
            }
            int pal[16][4];
            for (int k = 0; k < 16; k++)
                for (int c = 0; c < 4; c++) pal[k][c] = (e[0][c] * (64 - k_w4[k]) + e[1][c] * k_w4[k] + 32) >> 6;
            long err = 0;
            int idx[16];
            for (int i = 0; i < 16; i++) {
                long be = -1;
                for (int k = 0; k < 16; k++) {
                    long d = 0;
                    for (int c = 0; c < 4; c++) { const long t = pal[k][c] - in[i * 4 + c]; d += t * t; }
                    if (be < 0 || d < be) be = d, idx[i] = k;
                }
                err += be;
            }
            if (best_err < 0 || err < best_err) {
                best_err = err, best_p[0] = p0, best_p[1] = p1;
                memcpy(best_e, q, sizeof q), memcpy(best_idx, idx, sizeof idx);
            }
        }
    if (best_idx[0] & 8) {  // the anchor index's top bit is implied 0: swap the endpoints
        for (int c = 0; c < 4; c++) std::swap(best_e[0][c], best_e[1][c]);
        std::swap(best_p[0], best_p[1]);
        for (int i = 0; i < 16; i++) best_idx[i] = 15 - best_idx[i];
    }
    memset(blk, 0, 16);
    int pos = 0;
    auto put = [&](int v, int n) { for (int i = 0; i < n; i++, pos++) blk[pos >> 3] |= ((v >> i) & 1) << (pos & 7); };
    put(1 << 6, 7);  // mode 6
    for (int c = 0; c < 4; c++) put(best_e[0][c], 7), put(best_e[1][c], 7);
    put(best_p[0], 1), put(best_p[1], 1);
    for (int i = 0; i < 16; i++) put(best_idx[i], i ? 4 : 3);
}
